define(["core/ajax"],function(Ajax){const init=function(bookflowId,trackProgress){document.querySelectorAll(".bookflow-content-disclosure details").forEach(function(details){details.addEventListener("toggle",function(){if(!details.open||!trackProgress){return}const block=details.closest(".bookflow-content");Ajax.call([{methodname:"mod_bookflow_mark_content_completed",args:{bookflowid:bookflowId,contentid:Number(block.dataset.contentId),metric:100,details:JSON.stringify({visited:[0]})}}])[0].catch(function(){})})})};return{init:init}});